    let mut notes = vec![
        Note { id: "1".to_string(), pinned: false },
        Note { id: "2".to_string(), pinned: true },
    ];
    pin(&mut notes, "nonexistent");
    // Pinned states should remain unchanged
    assert!(!notes[0].pinned);
    assert!(notes[1].pinned);
}

#[test]
fn unpin_nonexistent_id_is_noop() {
    let mut notes = vec![
        Note { id: "1".to_string(), pinned: true },
        Note { id: "2".to_string(), pinned: false },
    ];
    unpin(&mut notes, "nonexistent");
    // Pinned states should remain unchanged
    assert!(notes[0].pinned);
    assert!(!notes[1].pinned);
}

#[test]
fn ordered_pinned_first_groups_and_preserves_order() {
    let notes = vec![
        Note { id: "1".to_string(), pinned: false },
        Note { id: "2".to_string(), pinned: true },
        Note { id: "3".to_string(), pinned: false },
        Note { id: "4".to_string(), pinned: true },
        Note { id: "5".to_string(), pinned: false },
    ];

    let ordered = ordered_pinned_first(&notes);

    // 1. Verify all notes are present (no duplicates or losses)
    assert_eq!(ordered.len(), notes.len());

    // 2. Verify every pinned note appears before every unpinned note
    let mut encountered_unpinned = false;
    for note in &ordered {
        if note.pinned {
            assert!(!encountered_unpinned, "Pinned note appeared after an unpinned note");
        } else {
            encountered_unpinned = true;
        }
    }

    // 3. Verify relative order of pinned notes is preserved
    let pinned_ids: Vec<&str> = ordered
        .iter()
        .filter(|n| n.pinned)
        .map(|n| n.id.as_str())
        .collect();
    assert_eq!(pinned_ids, vec!["2", "4"]);

    // 4. Verify relative order of unpinned notes is preserved
    let unpinned_ids: Vec<&str> = ordered
        .iter()
        .filter(|n| !n.pinned)
        .map(|n| n.id.as_str())
        .collect();
    assert_eq!(unpinned_ids, vec!["1", "3", "5"]);
}
